  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "preview", "--name", "test-preview"], { cwd: dir, env });
  let out = "";
  child.stdout.on("data", (d) => { out += d; });
  child.stderr.on("data", (d) => { out += d; });
  const timer = setTimeout(() => child.kill("SIGKILL"), 80000);
  child.on("close", (code) => {
    clearTimeout(timer);
    server.close();
    const created = reqs.filter((r) => r.m === "POST" && r.u === base);
    if (code === 0 && created.length === 1) {
      let body;
      try { body = JSON.parse(created[0].b); } catch (e) { broken("create Worker body is not JSON: " + created[0].b); }
      if (body.name !== "test-worker") broken("created Worker has name " + body.name);
      if (!reqs.some((r) => r.m === "POST" && r.u === base + "/test-worker/previews/p1/deployments")) broken("no Preview deployment was created");
      console.log("OK: wrangler preview created the missing parent Worker, then the Preview");
      process.exit(0);
    }
    if (code !== 0 && created.length === 0 && out.includes("previews/test-preview") && out.includes("10007")) symptom("wrangler preview failed with an API error on the Preview endpoint instead of creating the missing parent Worker");
    broken("exit " + code + ", " + created.length + " create-Worker requests; output: " + out.slice(-1500));
  });
});

